def blacksmith_has_available_buildings() -> bool:
    if selected_character_type != "blacksmith":
        return False
    if blacksmith_turret_blueprint_active or blacksmith_divine_blueprint_active:
        return False
    if blacksmith_hammer_shock_charging or not blacksmith_hammer_available:
        return False
    turret_available = not blacksmith_turret_active and not blacksmith_turret_blueprint_active
    divine_available = (
        blacksmith_divine_stone_state is None
        and not blacksmith_divine_blueprint_active
    )
    return turret_available or divine_available


def blacksmith_open_build_menu():
    global blacksmith_build_menu_active, blacksmith_down_hold_frames
    if not blacksmith_has_available_buildings():
        return
    if 'PLAYER' not in globals() or PLAYER is None:
        return
    blacksmith_build_menu_active = True
    blacksmith_down_hold_frames = 0


def blacksmith_close_build_menu():
    global blacksmith_build_menu_active, blacksmith_down_hold_frames
    blacksmith_build_menu_active = False
    blacksmith_down_hold_frames = 0


def blacksmith_can_build(option: str) -> bool:
    if option == "turret":
        return not blacksmith_turret_active and not blacksmith_turret_blueprint_active
    if option == "divine_stone":
        return (
            blacksmith_divine_stone_state is None
            and not blacksmith_divine_blueprint_active
        )
    return False


def blacksmith_start_divine_stone():
    global blacksmith_divine_blueprint_active, blacksmith_divine_blueprint_rect
    global blacksmith_divine_build_progress, blacksmith_divine_partial_drain
    if (
        blacksmith_divine_stone_state is not None
        or blacksmith_divine_blueprint_active
        or 'PLAYER' not in globals()
    ):
        return False
    blueprint_width = BLACKSMITH_DIVINE_STONE_SIZE[0]
    blueprint_height = BLACKSMITH_DIVINE_STONE_SIZE[1] + BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT
    rect = pygame.Rect(0, 0, blueprint_width, blueprint_height)
    base_x = max(blueprint_width // 2, min(WIDTH - blueprint_width // 2, PLAYER.centerx))
    base_y = HEIGHT - 5
    rect.midbottom = (base_x, base_y)
    blacksmith_divine_blueprint_rect = rect
    blacksmith_divine_build_progress = 0
    blacksmith_divine_partial_drain = 0.0
    blacksmith_divine_blueprint_active = True
    try:
        play_sound_with_volume(SOUND_ITEM_GET)
    except Exception:
        pass
    effects_manager.spawn_construction_smoke(rect.centerx, rect.bottom - 12, count=6, spread=24)
    return True


def blacksmith_select_build_option(option: str):
    global blacksmith_build_menu_active
    if selected_character_type != "blacksmith":
        return
    if option not in BLACKSMITH_BUILD_OPTIONS:
        return
    if not blacksmith_can_build(option):
        return
    blacksmith_close_build_menu()
    if option == "turret":
        handle_blacksmith_turret_input(False, True, True)
    elif option == "divine_stone":
        blacksmith_start_divine_stone()

