def draw_tutorial_progress_bar():
    """튜토리얼 전체 진행도 바 표시 (상단)"""
    global tutorial_current_chapter
    
    if current_stage != 50:  # 튜토리얼 스테이지가 아니면 표시하지 않음
        return
    
    # 폰트 설정
    font_small = FontStyle.small()  # 18pt
    font_medium = FontStyle.body()  # 24pt
    
    # 진행도 바 설정
    bar_width = 600
    bar_height = 40
    bar_x = (WIDTH - bar_width) // 2
    bar_y = 20
    
    # 배경 패널
    panel_surface = pygame.Surface((bar_width + 20, bar_height + 40), pygame.SRCALPHA)
    panel_surface.fill((20, 20, 40, 200))  # 반투명 배경
    pygame.draw.rect(panel_surface, (100, 200, 255, 100), (0, 0, bar_width + 20, bar_height + 40), 2)
    SCREEN.blit(panel_surface, (bar_x - 10, bar_y - 10))
    
    # 챕터 정보
    chapters = [
        {"name": "BASIC", "korean": "기본기"},
        {"name": "DASH", "korean": "대쉬"},
        {"name": "DRIVE", "korean": "드라이브"}
    ]
    
    # 각 챕터별 진행도 표시
    chapter_width = bar_width // 3
    for i, chapter in enumerate(chapters):
        chapter_x = bar_x + i * chapter_width
        chapter_num = i + 1
        
        # 챕터 박스 색상 결정
        if chapter_num < tutorial_current_chapter:
            # 완료된 챕터 - 초록색
            box_color = (50, 200, 50, 150)
            border_color = (100, 255, 100)
            text_color = (200, 255, 200)
            status_icon = "✓"
        elif chapter_num == tutorial_current_chapter:
            # 현재 챕터 - 파란색 + 애니메이션
            glow = int(50 + 30 * abs(math.sin(pygame.time.get_ticks() * 0.003)))
            box_color = (50, 100 + glow, 200, 150)
            border_color = (100, 150 + glow, 255)
            text_color = (255, 255, 255)
            status_icon = "▶"
        else:
            # 잠긴 챕터 - 회색
            box_color = (50, 50, 50, 100)
            border_color = (100, 100, 100)
            text_color = (150, 150, 150)
            status_icon = "🔒"
        
        # 챕터 박스 그리기
        chapter_rect = pygame.Rect(chapter_x, bar_y, chapter_width - 2, bar_height)
        pygame.draw.rect(SCREEN, box_color, chapter_rect)
        pygame.draw.rect(SCREEN, border_color, chapter_rect, 2)
        
        # 챕터 이름과 상태 아이콘
        chapter_text = f"{status_icon} {chapter['name']}"
        text_surface = font_small.render(chapter_text, True, text_color)
        text_rect = text_surface.get_rect(center=(chapter_x + chapter_width // 2, bar_y + bar_height // 2))
        SCREEN.blit(text_surface, text_rect)
        
        # 한글 이름 (아래쪽에 작게)
        korean_surface = font_small.render(chapter['korean'], True, text_color)
        korean_rect = korean_surface.get_rect(center=(chapter_x + chapter_width // 2, bar_y + bar_height + 15))
        SCREEN.blit(korean_surface, korean_rect)
    
    # 현재 챕터 강조 표시
    if 1 <= tutorial_current_chapter <= 3:
        current_x = bar_x + (tutorial_current_chapter - 1) * chapter_width
        # 깜빡이는 테두리
        if pygame.time.get_ticks() % 1000 < 500:
            pygame.draw.rect(SCREEN, (255, 255, 100), 
                           (current_x - 2, bar_y - 2, chapter_width + 2, bar_height + 4), 3)

def init_tutorial_success_feedback(message, level="normal"):
    """실시간 튜토리얼 성공 피드백 초기화 (비차단 방식)"""
    global tutorial_success_feedback_active, tutorial_success_feedback_message
    global tutorial_success_feedback_level, tutorial_success_feedback_timer
    global tutorial_success_feedback_particles
    
    tutorial_success_feedback_active = True
    tutorial_success_feedback_message = message
    tutorial_success_feedback_level = level
    tutorial_success_feedback_timer = 90  # 1.5초간 표시
    
    # 피드백 레벨에 따른 파티클 생성
    if level == "perfect":
        particle_colors = [(255, 255, 100), (255, 200, 50), (255, 255, 200)]
        num_particles = 30
    elif level == "great":
        particle_colors = [(150, 255, 150), (100, 200, 100), (200, 255, 200)]
        num_particles = 20
    else:  # normal
        particle_colors = [(150, 200, 255), (100, 150, 200), (200, 230, 255)]
        num_particles = 15
    
    # 파티클 초기화
    tutorial_success_feedback_particles = []
    for _ in range(num_particles):
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(2, 8)
        tutorial_success_feedback_particles.append({
            'x': WIDTH // 2,
            'y': HEIGHT // 2,
            'vx': math.cos(angle) * speed,
            'vy': math.sin(angle) * speed,
            'life': 60,
            'color': random.choice(particle_colors),
            'size': random.randint(3, 8)
        })

def draw_tutorial_success_feedback():
    """실시간 튜토리얼 성공 피드백 그리기 (메인 게임 루프에서 호출)"""
    global tutorial_success_feedback_active, tutorial_success_feedback_timer
    global tutorial_success_feedback_particles
    
    if not tutorial_success_feedback_active:
        return
    
    # 타이머 감소
    tutorial_success_feedback_timer -= 1
    if tutorial_success_feedback_timer <= 0:
        tutorial_success_feedback_active = False
        tutorial_success_feedback_particles = []
        return
    
    # 폰트 설정
    font_large = FontStyle.subtitle()  # 32pt
    
    # 피드백 레벨에 따른 색상
    if tutorial_success_feedback_level == "perfect":
        main_color = (255, 215, 0)  # 금색
    elif tutorial_success_feedback_level == "great":
        main_color = (100, 255, 100)  # 초록색
    else:  # normal
        main_color = (100, 200, 255)  # 파란색
    
    # 파티클 업데이트 및 그리기
    for particle in tutorial_success_feedback_particles[:]:
        particle['x'] += particle['vx']
        particle['y'] += particle['vy']
        particle['vy'] += 0.2  # 중력
        particle['life'] -= 1
        particle['size'] = max(1, particle['size'] - 0.1)
        
        if particle['life'] > 0:
            # 별 모양 그리기
            star_points = []
            for i in range(10):
                angle = i * math.pi / 5
                if i % 2 == 0:
                    r = particle['size']
                else:
                    r = particle['size'] / 2
                x = particle['x'] + r * math.cos(angle - math.pi / 2)
                y = particle['y'] + r * math.sin(angle - math.pi / 2)
                star_points.append((x, y))
            
            if len(star_points) >= 3:
                pygame.draw.polygon(SCREEN, particle['color'], star_points)
        else:
            tutorial_success_feedback_particles.remove(particle)
    
    # 메시지 표시 (중앙)
    text_scale = 1.0 + 0.2 * abs(math.sin(tutorial_success_feedback_timer * 0.1))  # 펠스 효과
    text_surface = font_large.render(tutorial_success_feedback_message, True, main_color)
    text_surface = pygame.transform.scale(text_surface, 
                                         (int(text_surface.get_width() * text_scale),
                                          int(text_surface.get_height() * text_scale)))
    text_rect = text_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2))
    
    # 텍스트 배경 (반투명)
    bg_surface = pygame.Surface((text_rect.width + 40, text_rect.height + 20), pygame.SRCALPHA)
    bg_surface.fill((0, 0, 0, 100))
    bg_rect = bg_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2))
    SCREEN.blit(bg_surface, bg_rect)
    
    # 텍스트 그리기
    SCREEN.blit(text_surface, text_rect)

def show_tutorial_success_feedback_blocking(message, level="normal"):
    """튜토리얼 성공 시 긍정적 피드백 표시 (차단 방식, 최종 달성용)"""
    clock = pygame.time.Clock()
    
    # 폰트 설정
    font_large = FontStyle.subtitle()  # 32pt
    font_medium = FontStyle.body()  # 24pt
    
    # 피드백 레벨에 따른 색상과 이펙트
    if level == "perfect":
        main_color = (255, 215, 0)  # 금색
        particle_colors = [(255, 255, 100), (255, 200, 50), (255, 255, 200)]
        num_particles = 30
    elif level == "great":
        main_color = (100, 255, 100)  # 초록색
        particle_colors = [(150, 255, 150), (100, 200, 100), (200, 255, 200)]
        num_particles = 20
    else:  # normal
        main_color = (100, 200, 255)  # 파란색
        particle_colors = [(150, 200, 255), (100, 150, 200), (200, 230, 255)]
        num_particles = 15
    
    # 파티클 초기화
    particles = []
    for _ in range(num_particles):
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(2, 8)
        particles.append({
            'x': WIDTH // 2,
            'y': HEIGHT // 2,
            'vx': math.cos(angle) * speed,
            'vy': math.sin(angle) * speed,
            'life': 60,
            'color': random.choice(particle_colors),
            'size': random.randint(3, 8)
        })
    
    # 애니메이션 루프 (1.5초간 칭찬 애니메이션) - 원래대로 복원
    animation_duration = 90  # 1.5초
    for frame in range(animation_duration):
        # 화면 그리기 (게임 화면 유지)
        draw_field()
        draw_objects()
        
        # 파티클 업데이트 및 그리기
        for particle in particles[:]:
            particle['x'] += particle['vx']
            particle['y'] += particle['vy']
            particle['vy'] += 0.2  # 중력
            particle['life'] -= 1
            particle['size'] = max(1, particle['size'] - 0.1)
            
            if particle['life'] > 0:
                # 별 모양 그리기
                star_points = []
                for i in range(10):
                    angle = i * math.pi / 5
                    if i % 2 == 0:
                        r = particle['size']
                    else:
                        r = particle['size'] / 2
                    x = particle['x'] + r * math.cos(angle - math.pi / 2)
                    y = particle['y'] + r * math.sin(angle - math.pi / 2)
                    star_points.append((x, y))
                
                if len(star_points) >= 3:
                    pygame.draw.polygon(SCREEN, particle['color'], star_points)
            else:
                particles.remove(particle)
        
        # 메시지 표시 (중앙)
        text_scale = 1.0 + 0.2 * abs(math.sin(frame * 0.1))  # 펄스 효과
        text_surface = font_large.render(message, True, main_color)
        text_surface = pygame.transform.scale(text_surface, 
                                             (int(text_surface.get_width() * text_scale),
                                              int(text_surface.get_height() * text_scale)))
        text_rect = text_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2))
        
        # 텍스트 배경 (반투명)
        bg_surface = pygame.Surface((text_rect.width + 40, text_rect.height + 20), pygame.SRCALPHA)
        bg_surface.fill((0, 0, 0, 100))
        bg_rect = bg_surface.get_rect(center=(WIDTH // 2, HEIGHT // 2))
        SCREEN.blit(bg_surface, bg_rect)
        
        # 텍스트 그리기
        SCREEN.blit(text_surface, text_rect)
        
        # 최종 달성 메시지일 때만 박수 애니메이션 추가 (대쉬 마스터, 완벽해요, 튜토리얼 완료)
        if "마스터" in message or "완벽해요" in message or "🎉" in message:
            # 박수 애니메이션 (양쪽에 손 그리기)
            clap_offset = abs(math.sin(frame * 0.3)) * 10  # 박수 움직임
            hand_size = 30
            
            # 왼쪽 손
            left_hand_x = text_rect.left - 50 - clap_offset
            left_hand_y = text_rect.centery
            
            # 오른쪽 손
            right_hand_x = text_rect.right + 50 + clap_offset
            right_hand_y = text_rect.centery
            
            # 손 그리기 (간단한 원과 손가락)
            # 왼쪽 손
            pygame.draw.circle(SCREEN, (255, 220, 180), (int(left_hand_x), int(left_hand_y)), hand_size)
            # 왼쪽 손가락들
            for i in range(4):
                finger_angle = -math.pi/6 + i * math.pi/12
                finger_x = left_hand_x + hand_size * math.cos(finger_angle)
                finger_y = left_hand_y + hand_size * math.sin(finger_angle) - 10
                pygame.draw.ellipse(SCREEN, (255, 220, 180), 
                                   (finger_x - 5, finger_y - 8, 10, 16))
            # 왼쪽 엄지
            pygame.draw.ellipse(SCREEN, (255, 220, 180), 
                              (left_hand_x + hand_size - 5, left_hand_y - 5, 12, 10))
            
            # 오른쪽 손
            pygame.draw.circle(SCREEN, (255, 220, 180), (int(right_hand_x), int(right_hand_y)), hand_size)
            # 오른쪽 손가락들
            for i in range(4):
                finger_angle = math.pi - math.pi/6 + i * math.pi/12
                finger_x = right_hand_x + hand_size * math.cos(finger_angle)
                finger_y = right_hand_y + hand_size * math.sin(finger_angle) - 10
                pygame.draw.ellipse(SCREEN, (255, 220, 180), 
                                   (finger_x - 5, finger_y - 8, 10, 16))
            # 오른쪽 엄지
            pygame.draw.ellipse(SCREEN, (255, 220, 180), 
                              (right_hand_x - hand_size - 7, right_hand_y - 5, 12, 10))
            
            # 박수 이펙트 (작은 별들)
            if frame % 10 < 5:  # 박수칠 때마다
                for _ in range(3):
                    star_x = (left_hand_x + right_hand_x) / 2 + random.randint(-20, 20)
                    star_y = left_hand_y + random.randint(-20, 20)
                    pygame.draw.circle(SCREEN, (255, 255, 100), 
                                     (int(star_x), int(star_y)), 3)
        
        pygame.display.flip()
        clock.tick(60)

def show_tutorial_success_feedback(message, level="normal"):
    """튜토리얼 성공 피드백 래퍼 함수 - 메시지에 따라 적절한 방식 선택"""
    # 최종 달성 메시지들 (게임 정지)
    if "마스터" in message or "완벽해요" in message or "🎉" in message:
        # 차단 방식 (게임 정지)
        show_tutorial_success_feedback_blocking(message, level)
    else:
        # 비차단 방식 (실시간 표시)
        init_tutorial_success_feedback(message, level)

