def record_victory_result(player_wins, boss_wins):
    """승부 결과 기록 (3-0, 3-1, 3-2 등)"""
    global player_analyzer, trade_point_system
    
    # 5:0 완승 시 보너스 트레이드 포인트 지급
    if player_wins == 5 and boss_wins == 0:
        if trade_point_system:
            # 화면 중앙 상단에 보너스 별 3개 생성 (더 눈에 띄게)
            bonus_x = WIDTH // 2
            bonus_y = HEIGHT // 3
            # 첫 번째 별
            trade_point_system.spawn_star(bonus_x - 40, bonus_y, "perfect_victory")
            # 두 번째 별 (중앙)
            trade_point_system.spawn_star(bonus_x, bonus_y, "perfect_victory")
            # 세 번째 별 (오른쪽)
            trade_point_system.spawn_star(bonus_x + 40, bonus_y, "perfect_victory")
            
            # 추가 시각 효과를 위한 메시지 표시 준비
            global perfect_victory_bonus_timer, victory_bonus_type
            perfect_victory_bonus_timer = 180  # 3초간 메시지 표시
            victory_bonus_type = "perfect"
            
            print("5:0 완승! 보너스 트레이드 포인트 +3")
    
    # 5:1 승리 시 보너스 트레이드 포인트 지급
    elif player_wins == 5 and boss_wins == 1:
        if trade_point_system:
            # 화면 중앙 상단에 보너스 별 2개 생성
            bonus_x = WIDTH // 2
            bonus_y = HEIGHT // 3
            trade_point_system.spawn_star(bonus_x - 20, bonus_y, "dominant_victory")
            trade_point_system.spawn_star(bonus_x + 20, bonus_y, "dominant_victory")
            
            # 추가 시각 효과를 위한 메시지 표시 준비 (global은 이미 위에서 선언됨)
            perfect_victory_bonus_timer = 180  # 3초간 메시지 표시
            victory_bonus_type = "dominant"
            
            print("5:1 승리! 보너스 트레이드 포인트 +2")
    
    # 5:2 승리 시 보너스 트레이드 포인트 지급
    elif player_wins == 5 and boss_wins == 2:
        if trade_point_system:
            # 화면 중앙 상단에 보너스 별 1개 생성
            bonus_x = WIDTH // 2
            bonus_y = HEIGHT // 3
            trade_point_system.spawn_star(bonus_x, bonus_y, "victory")
            
            # 추가 시각 효과를 위한 메시지 표시 준비
            perfect_victory_bonus_timer = 180  # 3초간 메시지 표시
            victory_bonus_type = "victory"
            
            print("5:2 소소한 승리! 보너스 트레이드 포인트 +1")
    
    if player_analyzer:
        try:
            player_analyzer.record_victory_result(player_wins, boss_wins)
        except:
            pass  # 조용히 실패
