def handle_boss():
    global boss_speed_boost_timer, BOSS_SPEED
    global boss_fake_move, boss_fake_start_time
    global is_player_serve, is_waiting_for_serve
    global boss_fake_during_player_serve
    global speed_defense_active, speed_defense_timer, speed_defense_last_activation, SPEED_DEFENSE_INTERVAL
    global serve_grace_period  # 난이도 하향 - 서브 유예 기간
    global boss_current_speed, boss_fail_timer
    global BOSS_ACCELERATION, BOSS_DECELERATION, BOSS_MAX_SPEED, BOSS_INSTANT_STOP_DECELERATION
    global waiting_start_time, wait_delay
    global boss_throwing, boss_throw_timer  #  Stage 5 화염탄 관련 변수
    global ball_vel
    global ragnarok_shock_playing  #  라그나로크 전기 감전 사운드 상태
    global boss_stunned_timer, boss_knockback_vel  #  화염병 스턴 관련 변수
    global stopwatch_active, stopwatch_timer  # ️ 스탑워치 관련 변수
    global whip_deactivation_active, boss_stunned_after_whip  #  상모돌리기 강제 해제 관련 변수
    global boss_knockback_timer, boss_knockback_distance  #  라그나로크 해머 넉백 관련 변수
    global boss_stun_timer, ragnarok_stun_pending  #  라그나로크 해머 스턴 관련 변수
    global head_shot_active, head_shot_timer  # 헤드샷 스턴 관련 변수
    
    
    #  수평 넉백 처리 (라그나로크 해머 + 코만도 총알)
    if boss_knockback_timer > 0:
        boss_knockback_timer -= 1
        
        # 라그나로크 해머 체크
        # Import already done globally at line 141
        legendary_manager = get_legendary_manager()
        is_ragnarok_knockback = "ragnarok_hammer" in legendary_manager.active_items
        
        # 수평 넉백 속도 적용 (라그나로크 해머 또는 코만도 총알)
        if abs(boss_knockback_vel) > 0.1:
            BOSS.x += boss_knockback_vel
            BOSS.x = max(0, min(WIDTH - PADDLE_WIDTH, BOSS.x))
            
            # 코만도 총알 넉백을 위한 감속 처리
            if boss_knockback_timer <= 18:  # 코만도 총알 (18프레임)
                boss_knockback_vel *= 0.85  # 매 프레임마다 15% 감속
            else:  # 라그나로크 해머 (더 긴 넉백)
                # 부드러운 감속 (초반엔 거의 감속 없이, 후반에 천천히)
                if boss_knockback_timer > 50:  # 처음 0.16초는 감속 없음
                    boss_knockback_vel *= 1.0  # 감속 없음
                elif boss_knockback_timer > 30:  # 중간 0.33초는 아주 약간 감속
                    boss_knockback_vel *= 0.99  # 1% 감속만
                else:  # 마지막 0.5초는 점진적 감속
                    boss_knockback_vel *= 0.97  # 3% 감속
            
            print(f"[DEBUG] 보스 넉백 업데이트 - timer: {boss_knockback_timer}, vel: {boss_knockback_vel:.2f}, pos: {BOSS.x:.2f}")
        
        # 라그나로크 해머만의 추가 효과
        if is_ragnarok_knockback:
            # 추가 흔들림 효과 (수평만, 넉백 초반에만 강하게)
            if boss_knockback_timer > 18:  # 처음 0.3초만 흔들림
                shake_x = random.uniform(-3, 3)
                BOSS.x += shake_x
                BOSS.x = max(0, min(WIDTH - PADDLE_WIDTH, BOSS.x))
            
            # 넉백이 끝나면 스턴 적용 (라그나로크 해머만)
            if boss_knockback_timer <= 1 and boss_knockback_timer > 0 and ragnarok_stun_pending > 0:  # 넉백 마지막 프레임 (타이밍 안정성 개선)
                boss_stun_timer = ragnarok_stun_pending
                ragnarok_stun_pending = 0  # 적용 후 초기화
                print(f"  ! boss_stun_timer = {boss_stun_timer}, : {boss_knockback_timer}")
                # 전기 감전 사운드 시작
                play_ragnarok_shock_sound()
                ragnarok_shock_playing = True
        
        # 넉백 중에는 보스 이동 불가
        boss_current_speed = 0  # 속도를 0으로 설정
        return  # AI 및 모든 이동 처리 차단
        
        # 타이머가 끝나면 원위치로 돌아오기 시작
        if boss_knockback_timer == 0:
            boss_knockback_distance = 0
            # 넉백이 완전히 끝났는데 스턴이 적용되지 않았다면 초기화
            if ragnarok_stun_pending > 0:
                print(f"   -   : {ragnarok_stun_pending}")
                ragnarok_stun_pending = 0
    
    #  라그나로크 해머 스턴 체크 - 스턴 중이면 모든 처리 차단
    if boss_stun_timer > 0:
        boss_stun_timer -= 1
        boss_current_speed = 0  # 속도를 0으로
        BOSS.x = BOSS.x  # 위치 고정 (현재 위치 유지)
        
        # 스턴이 끝나면 전기 감전 사운드 중지
        if boss_stun_timer == 0 and ragnarok_shock_playing:
            stop_ragnarok_shock_sound()
            ragnarok_shock_playing = False
            print("-")
        
        if boss_stun_timer % 20 == 0:  # 매 20프레임마다 디버그 출력
            print(f"   !  : {boss_stun_timer/60:.1f}, : {boss_current_speed}")
        return  # 스턴 중에는 모든 처리 차단
    
    # 바주카포 충돌 체크 및 폭발 처리
    if selected_character_type == "soldier":
        from item_effects.bazooka import get_bazooka_instance
        bazooka_inst = get_bazooka_instance()
        if bazooka_inst.equipped:
            # 모든 폭발 수집 (직접 명중 + 벽 충돌)
            all_explosions = []
            
            # 보스와의 직접 충돌 체크
            direct_explosions = bazooka_inst.check_boss_collision(BOSS, WIDTH)
            all_explosions.extend(direct_explosions)
            
            # 벽과의 충돌 체크
            wall_explosions = bazooka_inst.check_wall_collision()
            all_explosions.extend(wall_explosions)
            
            # 모든 폭발에 대해 처리
            for explosion in all_explosions:
                # 폭발 이펙트 생성
                create_bazooka_explosion(explosion["x"], explosion["y"])
                
                # 폭발 사운드 재생
                try:
                    if 'SOUND_GRENADE' in globals():
                        play_sound_with_volume(SOUND_GRENADE)  # 폭발 사운드
                    else:
                        print("🔊 바주카포 폭발 사운드 재생 (사운드 파일 없음)")
                except:
                    print("🔊 바주카포 사운드 재생 실패")
                
                # 폭발 범위 내 보스 체크 (수류탄과 동일한 로직)
                boss_center_x = BOSS.centerx
                boss_center_y = BOSS.centery
                distance = calculate_distance((boss_center_x, boss_center_y), (explosion["x"], explosion["y"]))
                
                if distance < explosion["radius"]:
                    # 보스 스턴 적용 (1.5초 = 90프레임)
                    boss_stunned_timer = 90  # 수류탄(120프레임)보다 짧음
                    
                    # 넉백 방향 결정 (수류탄과 동일)
                    direction = 1 if explosion["x"] < WIDTH / 2 else -1
                    knockback_power = compute_knockback_magnitude("bazooka")
                    boss_knockback_vel = _apply_boss_knockback_velocity(direction * knockback_power)
                    
                    print(f"🚀💥 바주카포 폭발! 보스 스턴 1.5초, 넉백: {boss_knockback_vel}")

    # 헤드샷 스턴 상태 처리 - 1.5초간 보스 완전 정지
    global head_shot_active, head_shot_timer
    if head_shot_active and head_shot_timer > 0:
        head_shot_timer -= 1
        boss_current_speed = 0  # 스턴 중에는 속도를 0으로
        BOSS.x = BOSS.x  # 위치 고정 (현재 위치 유지)
        if head_shot_timer <= 0:
            head_shot_active = False
            print("🎯 헤드샷 스턴 종료!")
        return  # 헤드샷 스턴 중에는 AI 완전 정지
    
    #  리그별 AI 모드 체크 및 분기 (4단계 리그 시스템)
    if ai_enabled and ai_mode == "junior":
        #  주니어리그: 초심자용 쉬운 AI (실수 25%)
        handle_boss_junior()
        return
    elif ai_enabled and ai_mode == "pro":
        #  프로리그: 표준 AI (실수 15%)
        handle_boss_pro()
        return
    elif ai_enabled and ai_mode == "champion":
        #  챔피언리그: 고급 AI (실수 8%)
        handle_boss_champion()
        return
    elif ai_enabled and ai_mode == "mythic":
        #  신화리그: 최강 AI (실수 2%)
        handle_boss_mythic()
        return
    #  새로운 보스 모드에서는 상단 보스가 handle_boss 역할
    if new_boss_mode_active:
        if selected_top_boss == 1:
            handle_lightning_master_as_top()  # 라이트닝 마스터
        elif selected_top_boss == 2:
            handle_ice_queen_as_top()  # 아이스 퀸
        return
    #  넉백 후 원위치 복귀 처리 (넉백이 없을 때만)
    if boss_knockback_timer == 0:
        # 라그나로크 해머가 활성화되어 있으면 복귀 속도 감소
        # Import already done globally at line 141
        legendary_manager = get_legendary_manager()
        
        if "ragnarok_hammer" in legendary_manager.active_items:
            # 라그나로크 해머 활성 시 복귀 완전 차단 (넉백 상태 유지)
            pass  # 아무것도 하지 않음 - 보스가 밀려난 위치에 그대로 유지
        else:
            # 원래 위치로 부드럽게 복귀
            if BOSS.y < BOSS_Y:
                BOSS.y += 2
                BOSS.y = min(BOSS_Y, BOSS.y)
    #  보스 스턴 상태 처리 (화염병 효과) - AI 비활성화 상태에서도 작동
    if boss_stunned_timer > 0:
        boss_stunned_timer -= 1
        # 넉백 적용
        BOSS.x += boss_knockback_vel
        BOSS.x = max(0, min(WIDTH - PADDLE_WIDTH, BOSS.x))
        # 감속
        boss_knockback_vel *= 0.85
        return  # 스턴 중에는 AI 비활성화
    # Stage 50 (튜토리얼) - 매우 쉬운 AI
    if current_stage == 50:
        # 튜토리얼에서 필요한 전역 변수 추가
        global fireball_last_cast, fireball_cooldown, ball_impact_boost
        
        # 튜토리얼 서브 대기 상태 처리
        if is_waiting_for_serve:
            time_now = pygame.time.get_ticks()
            
            # 보스 서브 차례
            if not is_player_serve:
                # 보스 패들 간보기 움직임
                def fake_motion():
                    style = random.randint(1, 4)
                    if style == 1:
                        return math.sin(time_now / 100) * 2.5
                    elif style == 2 and random.random() < 0.02:
                        return random.choice([-1, 1]) * random.randint(20, 30)
                    elif style == 3:
                        return math.sin(time_now / 300) * 4
                    elif style == 4 and random.random() < 0.015:
                        return random.choice([-1, 1]) * 10
                    return 0
                
                if boss_fake_move and time_now - boss_fake_start_time < wait_delay:
                    BOSS.centerx += fake_motion()
                
                if wait_delay > 0 and time_now - waiting_start_time >= wait_delay:
                    # 서브 실행 및 상태 업데이트
                    serve_result = physics_manager.serve_ball(is_player_serve, current_stage)
                    ball_vel = serve_result['ball_vel']
                    ball_impact_boost = serve_result['ball_impact_boost']
                    is_waiting_for_serve = serve_result['is_waiting_for_serve']
                    if serve_result['fireball_last_cast'] is not None:
                        fireball_last_cast = serve_result['fireball_last_cast']
                        fireball_cooldown = 1500  # 1.5초 쿨타임 강제 설정
                    play_serve_sound()
                    calculate_bounce(BOSS)
                    create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
                elif wait_delay == 0:
                    # 즉시 서브 실행
                    serve_result = physics_manager.serve_ball(is_player_serve, current_stage)
                    ball_vel = serve_result['ball_vel']
                    ball_impact_boost = serve_result['ball_impact_boost']
                    is_waiting_for_serve = serve_result['is_waiting_for_serve']
                    if serve_result['fireball_last_cast'] is not None:
                        fireball_last_cast = serve_result['fireball_last_cast']
                        fireball_cooldown = 1500  # 1.5초 쿨타임 강제 설정
                    play_serve_sound()
                    calculate_bounce(BOSS)
                    create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
            
            return  # 서브 중에는 일반 AI 실행 안함
        
        # 튜토리얼 전용 매우 쉬운 AI
        # 공의 미래 위치 예측 (매우 부정확하게)
        future_x = BALL.x
        
        # 큰 오차 추가 (초보자가 이길 수 있도록)
        error = random.randint(-150, 150)
        future_x += error
        
        # boss_speed_config[50]의 설정값 사용 (이미 50% 증가된 값)
        # BOSS_ACCELERATION, BOSS_MAX_SPEED 등은 start_stage에서 이미 설정됨
        max_speed = BOSS_MAX_SPEED  # boss_speed_config[50]에서 설정된 값 사용
        accel = BOSS_ACCELERATION   # boss_speed_config[50]에서 설정된 값 사용
        
        target_distance = future_x - BOSS.centerx
        
        # 때때로 완전히 잘못된 방향으로 이동 (20% 확률)
        if random.random() < 0.2:
            target_distance = -target_distance
        
        if abs(target_distance) < 50:  # 매우 큰 허용 범위
            boss_current_speed *= 0.7
        elif target_distance < 0:
            boss_current_speed = max(-max_speed, boss_current_speed - accel)
        else:
            boss_current_speed = min(max_speed, boss_current_speed + accel)
        
        # 위치 업데이트 with ground crack collision check
        proposed_x = BOSS.x + boss_current_speed
        proposed_boss_rect = pygame.Rect(proposed_x, BOSS.y, BOSS.width, BOSS.height)

        collision_crack = _boss_get_crack_collision(proposed_boss_rect, apply_response=True)
        if collision_crack:
            boss_current_speed = 0  # Stop the boss
            contact_x = _slide_boss_toward_crack_edge(BOSS.x, proposed_x, collision_crack, BOSS.width)
            if abs(contact_x - BOSS.x) > 0.01:
                BOSS.x = contact_x
                BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
            if random.random() < 0.1:  # 10% chance to print
                print(f"[CRACK BLOCKED - Tutorial] Boss cannot move from x={BOSS.x} to x={proposed_x}")
        else:
            BOSS.x = proposed_x
            BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
        return  # 튜토리얼 AI 완료
    
    # Stage 1 상모돌리기 강제 해제 모션 중 통제불능 상태
    if current_stage == 1 and boss_stunned_after_whip:
        # 완전 통제 불능 - 이동 불가
        boss_current_speed = 0
        BOSS.y = BOSS_Y  # Y 좌표를 기본 위치로 고정
        return  # AI 로직 완전 스킵
    
    # Stage 1 상모돌리기 중에는 이동 속도 제한
    if current_stage == 1 and whip_active:
        # 상모돌리기 중에는 이동 속도를 크게 제한 (30%로 감소)
        # 특히 플레이어 쪽(아래)으로 이동할 때 더 제한
        max_whip_speed = 1.5  # 최대 속도 제한
        
        # 현재 보스 속도를 크게 제한
        if abs(boss_current_speed) > max_whip_speed:
            boss_current_speed = max_whip_speed if boss_current_speed > 0 else -max_whip_speed
        
        # 속도를 추가로 30%로 감소
        boss_current_speed *= 0.3
        
        # 보스 위치 업데이트
        BOSS.x += boss_current_speed
        BOSS.x = max(0, min(WIDTH - BOSS.width, BOSS.x))
        
        # Y축 이동 차단 (앞으로 전진하지 못하게)
        BOSS.y = BOSS_Y  # Y 좌표를 기본 위치로 고정
        
        return  # 일반 AI 로직 스킵
    
    # 일반 보스 AI: 통합 보스 설정 (스테이지별 + 리그별 완전 연계)
    config = get_final_boss_config(current_stage, ai_mode)
    # --- Stage 5 화염탄 던지는 중에는 0.5초간 이동 금지 ---
    if current_stage == 5 and boss_throwing:
        boss_current_speed = 0
        # boss_throw_timer를 프레임 단위로 사용하고 있다면 30fps 기준 약 15프레임 = 0.5초
        boss_throw_timer -= 1
        if boss_throw_timer <= 0:
            boss_throwing = False
        return  #  이동 로직을 아예 스킵
    # --- Stage 6 항공모함 보스: 서브 대기 상태가 아닐 때만 근엄한 움직임 ---
    if current_stage == 6 and not is_waiting_for_serve:
        # 중앙 기준점 설정
        center_x = WIDTH // 2
        movement_range = 80  # 중앙에서 좌우 80픽셀 범위
        # 항공모함 보스 전용 움직임 변수 초기화
        if not hasattr(handle_boss, 'carrier_target'):
            handle_boss.carrier_target = center_x
            handle_boss.carrier_direction = 1
            handle_boss.carrier_pause_timer = 0
        # 일정 시간마다 방향 전환 (근엄한 패턴)
        handle_boss.carrier_pause_timer += 1
        # 180프레임(3초)마다 새로운 목표점 설정
        if handle_boss.carrier_pause_timer >= THREE_SECONDS_FRAMES:
            handle_boss.carrier_pause_timer = 0
            # 중앙 범위 내에서 새로운 목표점 선택
            handle_boss.carrier_target = center_x + random.randint(-movement_range, movement_range)
            handle_boss.carrier_target = max(BOSS.width // 2, 
                                           min(WIDTH - BOSS.width // 2, handle_boss.carrier_target))
        # 현재 목표점으로 천천히 이동 (근엄한 속도)
        carrier_speed = 1.5  # 매우 느린 속도
        if BOSS.centerx < handle_boss.carrier_target - 5:
            BOSS.centerx += carrier_speed
        elif BOSS.centerx > handle_boss.carrier_target + 5:
            BOSS.centerx -= carrier_speed
        # 경계 처리
        BOSS.centerx = max(BOSS.width // 2, min(WIDTH - BOSS.width // 2, BOSS.centerx))
        return  # 스테이지 6은 일반 AI 로직 스킵
    # --- 서브 대기 상태 처리 ---
    if is_waiting_for_serve:
        time_now = pygame.time.get_ticks()
        # 스테이지 6: 항공모함 보스는 서브 대기 중에도 특별한 움직임
        if current_stage == 6:
            # 항공모함 보스 서브 대기 중 움직임 (매우 미세한 좌우 이동)
            def carrier_standby_motion():
                return math.sin(time_now / 200) * 0.8  # 매우 느리고 작은 움직임
        else:
            # 보스 패들 간보기 움직임 (일반 스테이지)
            def fake_motion():
                style = random.randint(1, 4)
                if style == 1:
                    return math.sin(time_now / 100) * 2.5
                elif style == 2 and random.random() < 0.02:
                    return random.choice([-1, 1]) * random.randint(20, 30)
                elif style == 3:
                    return math.sin(time_now / 300) * 4
                elif style == 4 and random.random() < 0.015:
                    return random.choice([-1, 1]) * 10
                return 0
        # --- 보스 서브 차례 ---
        if not is_player_serve:
            if current_stage == 6:
                # 항공모함 보스는 항상 미세한 움직임
                BOSS.centerx += carrier_standby_motion()
                # 경계 처리
                BOSS.centerx = max(BOSS.width // 2, min(WIDTH - BOSS.width // 2, BOSS.centerx))
            elif boss_fake_move and time_now - boss_fake_start_time < wait_delay:
                BOSS.centerx += fake_motion()
            # 모든 스테이지에서 서브 로직 실행 (스테이지 6 포함)
            if wait_delay > 0 and time_now - waiting_start_time >= wait_delay:
                # 서브 실행 및 상태 업데이트
                serve_result = physics_manager.serve_ball(is_player_serve, current_stage)
                ball_vel = serve_result['ball_vel']
                ball_impact_boost = serve_result['ball_impact_boost']
                is_waiting_for_serve = serve_result['is_waiting_for_serve']
                # Stage 2에서 서브 후 유예 기간 설정 (난이도 하향)
                if current_stage == 2:
                    serve_grace_period = SERVE_GRACE_DURATION
                if serve_result['fireball_last_cast'] is not None:
                    fireball_last_cast = serve_result['fireball_last_cast']
                    fireball_cooldown = 1500  # 1.5초 쿨타임 강제 설정
                play_serve_sound()
                #  보스 서브 시에도 물리 효과 적용
                calculate_bounce(BOSS)
                #  보스 서브 시 타격 이펙트 생성
                create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
            if wait_delay == 0:
                # 서브 실행 및 상태 업데이트
                serve_result = physics_manager.serve_ball(is_player_serve, current_stage)
                ball_vel = serve_result['ball_vel']
                ball_impact_boost = serve_result['ball_impact_boost']
                is_waiting_for_serve = serve_result['is_waiting_for_serve']
                # Stage 2에서 서브 후 유예 기간 설정 (난이도 하향)
                if current_stage == 2:
                    serve_grace_period = SERVE_GRACE_DURATION
                if serve_result['fireball_last_cast'] is not None:
                    fireball_last_cast = serve_result['fireball_last_cast']
                    fireball_cooldown = 1500  # 1.5초 쿨타임 강제 설정
                play_serve_sound()
                #  보스 서브 시에도 물리 효과 적용
                calculate_bounce(BOSS)
                #  보스 서브 시 타격 이펙트 생성
                create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=False)
        # --- 플레이어 서브 차례 ---
        elif boss_fake_during_player_serve:
            if current_stage == 6:
                # 항공모함 보스는 플레이어 서브 중에도 미세한 움직임
                BOSS.centerx += carrier_standby_motion()
                # 경계 처리
                BOSS.centerx = max(BOSS.width // 2, min(WIDTH - BOSS.width // 2, BOSS.centerx))
            else:
                BOSS.centerx += fake_motion()
        return  # 서브 중에는 아래 일반 이동 로직 실행 안 함
    # --- 일반 AI 이동 로직 ---
    predict_frame = max(10, min(30, int(FPS / max(1, abs(ball_vel[0])))))
    # --- 기존 AI 로직 ---
    enhanced_fail_chance = config["fail_chance"]
    enhanced_predict_chance = config["predict_chance"]
    enhanced_predict_error = config["predict_error"]
    enhanced_fail_error = config["fail_error"]
    
    # Check if current position is blocked by cracks (stuck detection)
    if 'blacksmith_ground_cracks' in globals() and blacksmith_ground_cracks:
        # If boss has been trying to move but stuck for too long, try alternative direction
        if not hasattr(handle_boss, 'stuck_timer'):
            handle_boss.stuck_timer = 0
            handle_boss.last_x = BOSS.x
        
        # Check if boss hasn't moved much
        if abs(BOSS.x - handle_boss.last_x) < 2:  # Less than 2 pixels movement
            handle_boss.stuck_timer += 1
        else:
            handle_boss.stuck_timer = 0
            handle_boss.last_x = BOSS.x
        
        # If stuck for more than 30 frames, try to find alternative path
        if handle_boss.stuck_timer > 30:
            # Try to move to nearest free space
            for offset in [30, -30, 60, -60, 90, -90]:
                test_x = BOSS.x + offset
                if 0 <= test_x <= WIDTH - BOSS.width and _is_boss_movement_valid(test_x):
                    # Found a free space, set as temporary target
                    enhanced_predict_error = abs(offset) * 2
                    handle_boss.stuck_timer = 0
                    break
    
    # 조명탄 혼란 효과 체크 (최우선)
    if boss_confused_timer > 0:
        # 혼란 상태일 때는 완전히 랜덤하게 움직임 (공을 무시)
        if not hasattr(handle_boss, 'confusion_target_ai'):
            handle_boss.confusion_target_ai = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
            handle_boss.confusion_direction_timer_ai = 0
        # 30프레임마다 새로운 랜덤 위치 선택
        handle_boss.confusion_direction_timer_ai = getattr(handle_boss, 'confusion_direction_timer_ai', 0) + 1
        if handle_boss.confusion_direction_timer_ai >= HALF_SECOND_FRAMES:
            handle_boss.confusion_target_ai = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
            handle_boss.confusion_direction_timer_ai = 0
        # 랜덤 목표 지점으로 이동
        future_x = handle_boss.confusion_target_ai
        # 가끔 갑자기 방향 전환 (20% 확률)
        if random.random() < 0.2:
            future_x = random.randint(BOSS.width // 2, WIDTH - BOSS.width // 2)
    # --- 멍청 모드 처리 ---
    elif boss_fail_timer > 0:
        future_x = BALL.centerx + ball_vel[0] * predict_frame
        future_x += random.randint(-enhanced_fail_error, enhanced_fail_error)
        boss_fail_timer -= 1
    else:
        if random.random() < enhanced_fail_chance:
            boss_fail_timer = 60
            future_x = BALL.centerx + ball_vel[0] * predict_frame
            future_x += random.randint(-enhanced_fail_error, enhanced_fail_error)
        else:
            if random.random() < enhanced_predict_chance:
                future_x = BALL.centerx + ball_vel[0] * predict_frame
            else:
                future_x = BALL.centerx
            future_x += random.randint(-enhanced_predict_error, enhanced_predict_error)
    # Check if target is blocked by cracks and adjust if needed
    target_x = future_x
    if 'blacksmith_ground_cracks' in globals() and blacksmith_ground_cracks:
        # Check if the path to target is blocked
        if _check_path_blocked_by_cracks(BOSS.x, target_x, BOSS.width, BOSS.y, BOSS.height):
            # Target is blocked, find alternative target
            # Check both sides of the crack
            left_clear = False
            right_clear = False
            left_target = BOSS.x
            right_target = BOSS.x
            
            # Check left side
            for test_x in range(int(BOSS.x) - 10, 0, -10):
                if not _check_path_blocked_by_cracks(BOSS.x, test_x, BOSS.width, BOSS.y, BOSS.height):
                    left_target = test_x
                    left_clear = True
                    break
            
            # Check right side  
            for test_x in range(int(BOSS.x) + 10, WIDTH - BOSS.width, 10):
                if not _check_path_blocked_by_cracks(BOSS.x, test_x, BOSS.width, BOSS.y, BOSS.height):
                    right_target = test_x
                    right_clear = True
                    break
            
            # Choose the side that's closer to the original target but not blocked
            if left_clear and right_clear:
                if abs(left_target - target_x) < abs(right_target - target_x):
                    future_x = left_target
                else:
                    future_x = right_target
            elif left_clear:
                future_x = left_target
            elif right_clear:
                future_x = right_target
            else:
                # Both sides blocked, stop moving
                future_x = BOSS.centerx
                boss_current_speed = 0
    
    # --- 가속/감속 로직: 통합 설정 기반 ---
    # 스피드디펜스 활성화 시 전역 변수 사용, 아니면 config 사용
    if current_stage == 2 and speed_defense_active:
        enhanced_accel = BOSS_ACCELERATION
        enhanced_decel = BOSS_DECELERATION
        enhanced_max_speed = BOSS_MAX_SPEED
        enhanced_instant_stop = BOSS_INSTANT_STOP_DECELERATION
    else:
        enhanced_accel = config["accel"]
        enhanced_decel = config["decel"]
        enhanced_max_speed = config["max_speed"]
        enhanced_instant_stop = config["instant_stop"]
    #  화염 지대 내에서 속도 감소 효과 적용
    if boss_speed_reduction_active:
        enhanced_accel *= boss_speed_reduction_factor  # 가속도 50% 감소
        enhanced_max_speed *= boss_speed_reduction_factor  # 최대 속도 50% 감소
        # 현재 속도도 즉시 감소
        boss_current_speed *= boss_speed_reduction_factor
    
    # 이동 속도 감소 효과 적용
    slow_multiplier = 1.0
    if leg_shot_active:
        slow_multiplier *= LEG_SHOT_SPEED_REDUCTION
    if spider_mine_slow_active:
        slow_multiplier *= SPIDER_MINE_SLOW_FACTOR
    if slow_multiplier != 1.0:
        enhanced_accel *= slow_multiplier
        enhanced_max_speed *= slow_multiplier
        enhanced_decel *= slow_multiplier
        boss_current_speed *= slow_multiplier
    # 기존 AI 움직임 로직
    if future_x < BOSS.centerx:
        if boss_current_speed > -enhanced_max_speed:
            boss_current_speed -= enhanced_accel
    elif future_x > BOSS.centerx:
        if boss_current_speed < enhanced_max_speed:
            boss_current_speed += enhanced_accel
    else:
        if boss_current_speed > 0:
            boss_current_speed -= enhanced_decel
        elif boss_current_speed < 0:
            boss_current_speed += enhanced_decel
    # 급정지 처리
    if future_x < BOSS.centerx and boss_current_speed > 0:
        boss_current_speed -= enhanced_instant_stop
    elif future_x > BOSS.centerx and boss_current_speed < 0:
        boss_current_speed += enhanced_instant_stop
    # 이동 적용 with ground crack collision check
    proposed_x = BOSS.x + boss_current_speed
    proposed_boss_rect = pygame.Rect(proposed_x, BOSS.y, BOSS.width, BOSS.height)

    collision_crack = None
    if 'blacksmith_ground_cracks' in globals() and blacksmith_ground_cracks:
        collision_crack = _boss_get_crack_collision(proposed_boss_rect, apply_response=True)

    if collision_crack:
        boss_current_speed = 0
        contact_x = _slide_boss_toward_crack_edge(BOSS.x, proposed_x, collision_crack, BOSS.width)
        if abs(contact_x - BOSS.x) > 0.01:
            BOSS.x = contact_x
            BOSS.centerx = BOSS.x + BOSS.width // 2
        if random.random() < 0.1:  # 10% chance to print debug
            print(f"[CRACK BLOCKED - Main AI] Boss cannot move from x={BOSS.x} to x={proposed_x}")
    else:
        BOSS.centerx += boss_current_speed
        BOSS.centerx = max(BOSS.width // 2, min(WIDTH - BOSS.width // 2, BOSS.centerx))
        BOSS.x = BOSS.centerx - BOSS.width // 2
    # --- Stage 2 보스 스피드 디펜스 (위험감지센서 역할) ---
    if current_stage == 2:
        # 서브 유예 기간 카운트다운 (난이도 하향)
        if serve_grace_period > 0:
            serve_grace_period -= 1
        
        # 플레이어가 친 공이 보스에게 위험할 때 발동 (유예 기간 제외)
        if not speed_defense_active and speed_defense_timer <= 0 and ball_vel[1] < 0 and serve_grace_period <= 0:  # 공이 위로 향할 때
            # 공이 보스 근처에 도달할 시간 예측
            if BALL.centery < HEIGHT * 0.5:  # 공이 화면 상단 50% 지점 이상 (더 일찍 감지)
                time_to_reach_boss = abs((BOSS.centery - BALL.centery) / ball_vel[1]) if ball_vel[1] < 0 else float('inf')
                if time_to_reach_boss < 60:  # 1초 이내에 도달 예정 (더 여유있게)
                    predicted_x = BALL.centerx + ball_vel[0] * time_to_reach_boss
                    distance_to_predicted = abs(predicted_x - BOSS.centerx)
                    # 보스가 현재 속도로 이동해도 도달하기 어려운 위치인지 확인
                    boss_max_move = BOSS_MAX_SPEED_DEFAULT * time_to_reach_boss
                    # 위험 감지: 보스가 도달하기 어려운 거리 (더 민감하게)
                    if distance_to_predicted > boss_max_move * 0.8:  # 80% 이상 도달 어려움 (덜 민감) - 난이도 하향
                        # 10% 확률로 스피드디펜스 발동 (확률 증가)
                        if random.random() < 0.06:  # 6% 확률로 발동 (기존 10%) - 난이도 하향
                            # 발동 간격 체크 (25초)
                            current_time = pygame.time.get_ticks() // 16  # 프레임으로 변환
                            if current_time - speed_defense_last_activation >= SPEED_DEFENSE_INTERVAL:
                                speed_defense_active = True
                                speed_defense_timer = speed_defense_cooldown  # 3초 지속
                                speed_defense_last_activation = current_time
                                
                                # 현재 보스 속도의 200% (+100%)로 스피드디펜스 설정
                                # 리그와 스테이지에 따른 현재 보스 속도 가져오기
                                current_config = get_final_boss_config(current_stage, ai_mode if ai_enabled else "pro")
                                # 스피드디펜스: 현재 속도의 200% 적용
                                speed_multiplier = 1.5  # 50% 증가 (1.5배속) - 난이도 하향
                                BOSS_ACCELERATION = current_config["accel"] * speed_multiplier
                                BOSS_DECELERATION = current_config["decel"] * speed_multiplier
                                BOSS_MAX_SPEED = current_config["max_speed"] * speed_multiplier
                                BOSS_INSTANT_STOP_DECELERATION = current_config["instant_stop"] * speed_multiplier
                                # 즉시 목표 지점으로 가속 시작
                                if predicted_x < BOSS.centerx:
                                    boss_current_speed = -BOSS_MAX_SPEED * 0.2  # 왼쪽으로 초기 속도 부여 (최대속도의 20%) - 난이도 하향
                                else:
                                    boss_current_speed = BOSS_MAX_SPEED * 0.2   # 오른쪽으로 초기 속도 부여 (최대속도의 20%) - 난이도 하향
                                play_sound_with_volume(SOUND_DEFENSE_START)
                                print(f"스피드 디펜스 발동! 거리 차이: {distance_to_predicted:.1f}, 최대 이동 가능: {boss_max_move:.1f}")
        if speed_defense_timer > 0:
            speed_defense_timer -= 1
        if speed_defense_active and speed_defense_timer <= 0:
            speed_defense_active = False
            boss_trail.clear()  #  스피드 디펜스 종료 시 꼬리 효과 즉시 정리
            BOSS_ACCELERATION = BOSS_ACCELERATION_DEFAULT
            BOSS_DECELERATION = BOSS_DECELERATION_DEFAULT
            BOSS_MAX_SPEED = BOSS_MAX_SPEED_DEFAULT
            BOSS_INSTANT_STOP_DECELERATION = BOSS_INSTANT_STOP_DECELERATION_DEFAULT
def show_death_evaluation():
    """사망 시 실력 평가 화면 표시 - show_player_info() 호출"""
    # ESC 메뉴의 정보 화면과 동일한 플레이어 실력 분석을 표시
    show_player_info()
def show_result(won):
    global medal_score, current_stage, session_medal_earned
    global special_gauge, special_ready, special_active
    global speedboots_obtained, speedgear_obtained  #  패시브 아이템 효과 초기화용
