    global walls, pending_wall, wall_installing, wall_install_timer, wall_install_gauge_visible, passive_item_list, round_losses  #  벽돌 변수 추가
    global deuce_mode, deuce_wins, deuce_losses, deuce_goal  #  듀스 시스템 변수 추가
