        # 테크니컬조끼 추가
        if not items.technical_vest_obtained:
            technical_vest_icon = get_item_icon("technical_vest")
            available_items.append({"name": "technical_vest", "color": (100, 100, 200), "type": "passive", "icon": technical_vest_icon})
        # 연료파우치 추가
        if not items.fuel_pouch_obtained:
            fuel_pouch_icon = get_item_icon("fuel_pouch")
            available_items.append({"name": "fuel_pouch", "color": (200, 150, 100), "type": "passive", "icon": fuel_pouch_icon})
        # 블루투스링 추가
        if not items.bluetooth_ring_obtained:
            bluetooth_ring_icon = get_item_icon("bluetooth_ring")
            available_items.append({"name": "bluetooth_ring", "color": (100, 150, 200), "type": "passive", "icon": bluetooth_ring_icon})
