            # SCREEN을 임시로 temp_surface로 교체
            temp_screen = SCREEN
            SCREEN = temp_surface
            draw_field()
            draw_objects()
            draw_tutorial_ui()  # 튜토리얼 UI 표시
            draw_tutorial_dash_counter()  # 튜토리얼 대쉬 카운터 표시
            draw_tutorial_drive_counter()  # 튜토리얼 드라이브 카운터 표시
            draw_tutorial_power_counter()  # 튜토리얼 파워스매싱 카운터 표시
            draw_tutorial_success_feedback()  # 실시간 성공 피드백 표시
            draw_boss_health_bar()  #  체력형 보스 체력바 그리기
            draw_stage1_boss_gauge_bar()  # 스테이지 1 보스 게이지바 그리기
            draw_stage2_boss_gauge_bar()  # 스테이지 2 게이지바
            draw_laser_cannon_gauge()  #  레이저 쿨타임 게이지바
            # 원래 화면으로 복원하고 흔들림 적용
            SCREEN = temp_screen
            SCREEN.fill(BLACK)  # 원래 화면도 검은색으로 지우기
            SCREEN.blit(temp_surface, (screen_shake_offset_x, screen_shake_offset_y))
            
            # 스테이지별 효과를 UI 전에 그리기 (흔들림과 함께 적용)
            if current_stage == 1:
                # 스테이지1은 테두리 없음 - 무지개 테두리만 검은색으로 덮음
                pass
            elif current_stage == 2:
                # 임시 서페이스에 정글 효과 그리기 
                temp_jungle = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                # 정글 테두리를 임시 서페이스에 그리기
